            Assert.Equal(1, page.PageIndex);
        }
    }
}

using System;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            NotificationQueueHelper.DrainQueue();
            _service = new NotificationService();
        }

        public void Dispose()
        {
            _service.Dispose();
            NotificationQueueHelper.DrainQueue();
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotificationWithCorrectMessage()
        {
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("New Student 'John Doe' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_EnqueuesNotificationWithIdInMessage()
        {
            _service.SendNotification("Student", "1", null, EntityOperation.CREATE, "admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("New Student (ID: 1) has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateOperation_GeneratesUpdateMessage()
        {
            _service.SendNotification("Course", "101", "Math 101", EntityOperation.UPDATE, "admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Course 'Math 101' has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
        {
            _service.SendNotification("Course", "101", "Math 101", EntityOperation.DELETE, "admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Course 'Math 101' has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_SetsCreatedByToUserName()
        {
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "testuser");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("testuser", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsIsReadToFalse()
        {
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_Overload_WithoutDisplayName_DelegatesToFullOverload()
        {
            _service.SendNotification("Student", "42", EntityOperation.CREATE, "admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("Student", notification.Message);
            Assert.Contains("42", notification.Message);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _service.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_DequeuesInOrder()
        {
            _service.SendNotification("Type", "1", "First", EntityOperation.CREATE, "admin");
            _service.SendNotification("Type", "2", "Second", EntityOperation.UPDATE, "admin");
            _service.SendNotification("Type", "3", "Third", EntityOperation.DELETE, "admin");

            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();
            var third = _service.ReceiveNotification();

            Assert.Equal("1", first.EntityId);
            Assert.Equal("2", second.EntityId);
            Assert.Equal("3", third.EntityId);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            var exception = Record.Exception(() => _service.MarkAsRead(999));

            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();

            var exception = Record.Exception(() => service.Dispose());

            Assert.Null(exception);
        }

        [Fact]
        public void QueueCap_ExceedingMaxLength_OldestItemsDropped()
        {
            for (int i = 0; i < 510; i++)
            {
                _service.SendNotification("Item", i.ToString(), $"Item {i}", EntityOperation.CREATE, "admin");
            }

            int count = 0;
            while (_service.ReceiveNotification() != null)
            {
                count++;
            }

            Assert.True(count <= 500, $"Queue should be capped at 500 but had {count} items");
        }
    }
}

