using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            NotificationQueueHelper.DrainQueue();

            _context = TestDbContextFactory.Create();
            _controller = new StudentsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), Mock.Of<ITempDataProvider>());
        }

        public void Dispose()
        {
            _controller?.Dispose();
            _context?.Dispose();
        }

        private Student CreateStudent(string lastName, string firstName, DateTime enrollmentDate)
        {
            var student = new Student
            {
                LastName = lastName,
                FirstMidName = firstName,
                EnrollmentDate = enrollmentDate
            };
            _context.Students.Add(student);
            _context.SaveChanges();
            return student;
        }

        private void SeedStudents()
        {
            CreateStudent("Adams", "Alice", new DateTime(2023, 1, 15));
            CreateStudent("Baker", "Bob", new DateTime(2022, 6, 10));
            CreateStudent("Clark", "Charlie", new DateTime(2024, 3, 20));
        }

        // ─── Index Tests ───

        [Fact]
        public void Index_DefaultSort_OrdersByLastNameAscending()
        {
            SeedStudents();

            var result = _controller.Index(null, null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(3, model.Count);
            Assert.Equal("Adams", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Clark", model[2].LastName);
        }

        [Fact]
        public void Index_NameDescSort_OrdersByLastNameDescending()
        {
            SeedStudents();

            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("Clark", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Adams", model[2].LastName);
        }

        [Fact]
        public void Index_DateSort_OrdersByEnrollmentDateAscending()
        {
            SeedStudents();

            var result = _controller.Index("Date", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("Baker", model[0].LastName);   // 2022
            Assert.Equal("Adams", model[1].LastName);   // 2023
            Assert.Equal("Clark", model[2].LastName);   // 2024
        }

        [Fact]
        public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
        {
            SeedStudents();

            var result = _controller.Index("date_desc", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal("Clark", model[0].LastName);   // 2024
            Assert.Equal("Adams", model[1].LastName);   // 2023
            Assert.Equal("Baker", model[2].LastName);   // 2022
        }

        [Fact]
        public void Index_SearchString_FiltersStudents()
        {
            SeedStudents();

            var result = _controller.Index(null, null, "Baker", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Baker", model[0].LastName);
        }

        [Fact]
        public void Index_SearchString_FiltersStudentsByFirstName()
        {
            SeedStudents();

            var result = _controller.Index(null, null, "Alice", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Adams", model[0].LastName);
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            SeedStudents();

            var result = _controller.Index(null, "Baker", null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Baker", model[0].LastName);
            Assert.Equal("Baker", _controller.ViewBag.CurrentFilter);
        }

        [Fact]
        public void Index_NewSearchString_ResetsPageTo1()
        {
            SeedStudents();

            var result = _controller.Index(null, null, "Adams", 5) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_SetsViewBagProperties()
        {
            SeedStudents();

            _controller.Index("Date", null, null, null);

            Assert.Equal("Date", (string)_controller.ViewBag.CurrentSort);
            Assert.Equal("", (string)_controller.ViewBag.NameSortParm);
            Assert.Equal("date_desc", (string)_controller.ViewBag.DateSortParm);
            Assert.Null((string)_controller.ViewBag.CurrentFilter);
        }

        [Fact]
        public void Index_Pagination_ReturnsCorrectPage()
        {
            // Seed 12 students so we get 2 pages (pageSize=10)
            for (int i = 1; i <= 12; i++)
            {
                CreateStudent($"Student{i:D2}", $"First{i}", new DateTime(2023, 1, i));
            }

            var result = _controller.Index(null, null, null, 2) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.PageIndex);
            Assert.Equal(2, model.Count);
            Assert.True(model.HasPreviousPage);
            Assert.False(model.HasNextPage);
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index(null, null, null, null);

            Assert.IsType<ViewResult>(result);
        }

        // ─── Details Tests ───

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            var student = CreateStudent("Smith", "John", new DateTime(2023, 5, 1));

            var result = _controller.Details(student.ID) as ViewResult;

            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Smith", model.LastName);
            Assert.Equal("John", model.FirstMidName);
        }

        [Fact]
        public void Details_IncludesEnrollments()
        {
            var student = CreateStudent("Smith", "John", new DateTime(2023, 5, 1));
            var course = new Course { CourseID = 1001, Title = "Math", Credits = 3, DepartmentID = 0 };
            _context.Courses.Add(course);
            _context.Enrollments.Add(new Enrollment
            {
                StudentID = student.ID,
                CourseID = course.CourseID,
                Grade = Grade.A
            });
            _context.SaveChanges();

            var result = _controller.Details(student.ID) as ViewResult;

            var model = Assert.IsType<Student>(result.Model);
            Assert.NotNull(model.Enrollments);
            Assert.Single(model.Enrollments);
            Assert.Equal(1001, model.Enrollments.First().CourseID);
        }

        // ─── Create GET Tests ───

        [Fact]
        public void Create_Get_ReturnsViewWithStudentWithTodaysDate()
        {
            var result = _controller.Create() as ViewResult;

            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        // ─── Create POST Tests ───

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_Post_ValidStudent_SavesStudentToDb()
        {
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            _controller.Create(student);

            var saved = _context.Students.FirstOrDefault(s => s.LastName == "Doe");
            Assert.NotNull(saved);
            Assert.Equal("Jane", saved.FirstMidName);
            Assert.Equal(new DateTime(2023, 9, 1), saved.EnrollmentDate);
        }

        [Fact]
        public void Create_Post_ValidStudent_SendsNotification()
        {
            NotificationQueueHelper.DrainQueue();
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            _controller.Create(student);

            using var svc = new NotificationService();
            var notification = svc.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("CREATE", notification.Operation);
        }

        [Fact]
        public void Create_Post_MinValueDate_AddsModelError()
        {
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_DateBelow1753_AddsModelError()
        {
            var student = new Student
            {
