namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;

        public CoursesControllerTests()
        {
            NotificationQueueHelper.DrainQueue();

            _context = TestDbContextFactory.Create();

            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockEnv.Setup(e => e.ContentRootPath).Returns("/fakepath");

            _mockLogger = new Mock<ILogger<CoursesController>>();

            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), Mock.Of<ITempDataProvider>());
        }

        public void Dispose()
        {
            _controller?.Dispose();
            _context?.Dispose();
        }

        private Department CreateDepartment(string name = "Engineering", decimal budget = 100000m)
        {
            var dept = new Department
            {
                Name = name,
                Budget = budget,
                StartDate = new DateTime(2023, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course CreateCourse(int courseId, string title, int credits, int departmentId)
        {
            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = credits,
                DepartmentID = departmentId
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        // ─── Index Tests ───

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            var dept = CreateDepartment();
            CreateCourse(1001, "Calculus", 3, dept.DepartmentID);
            CreateCourse(1002, "Physics", 4, dept.DepartmentID);

            var result = _controller.Index() as ViewResult;

            var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Index_IncludesDepartment()
        {
            var dept = CreateDepartment("Math");
            CreateCourse(2001, "Algebra", 3, dept.DepartmentID);

            var result = _controller.Index() as ViewResult;

            var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
            Assert.NotNull(model[0].Department);
            Assert.Equal("Math", model[0].Department.Name);
        }

        // ─── Details Tests ───

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            var dept = CreateDepartment();
            var course = CreateCourse(3001, "Chemistry", 3, dept.DepartmentID);

            var result = _controller.Details(3001) as ViewResult;

            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Chemistry", model.Title);
            Assert.Equal(3, model.Credits);
        }

        // ─── Create GET Tests ───

        [Fact]
        public void Create_Get_ReturnsViewWithNewCourse()
        {
            CreateDepartment();

            var result = _controller.Create() as ViewResult;

            Assert.IsType<Course>(result.Model);
        }

        [Fact]
        public void Create_Get_SetsDepartmentSelectList()
        {
            CreateDepartment("Math");

            _controller.Create();

            Assert.NotNull(_controller.ViewBag.DepartmentID);
            var selectList = Assert.IsType<SelectList>(_controller.ViewBag.DepartmentID);
            Assert.Single(selectList);
        }

        // ─── Create POST Tests ───

        [Fact]
        public void Create_Post_ValidCourse_NoFile_SavesAndRedirects()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 4001,
                Title = "Biology",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Create(course, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.NotNull(_context.Courses.Find(4001));
        }

        [Fact]
        public void Create_Post_ValidCourse_SendsNotification()
        {
            NotificationQueueHelper.DrainQueue();
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 4002,
                Title = "History",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            _controller.Create(course, null);

            using var svc = new NotificationService();
            var notification = svc.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("CREATE", notification.Operation);
        }

        [Fact]
        public void Create_Post_InvalidExtension_AddsModelError()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 4003,
                Title = "Art",
                Credits = 2,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("malware.exe");
            mockFile.Setup(f => f.Length).Returns(1024);

            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_FileTooLarge_AddsModelError()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 4004,
                Title = "Music",
                Credits = 2,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("photo.jpg");
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB

            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            var dept = CreateDepartment();
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course
            {
                CourseID = 4005,
                Title = "",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Create(course, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Course>(viewResult.Model);
        }

        // ─── Edit GET Tests ───

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithCourse()
        {
            var dept = CreateDepartment();
