            var result = _controller.Edit(5001) as ViewResult;

            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Geography", model.Title);
        }

        [Fact]
        public void Edit_Get_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Edit(99999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_SetsDepartmentSelectList()
        {
            var dept = CreateDepartment("Science");
            CreateCourse(5002, "Physics", 4, dept.DepartmentID);

            _controller.Edit(5002);

            Assert.NotNull(_controller.ViewBag.DepartmentID);
            var selectList = Assert.IsType<SelectList>(_controller.ViewBag.DepartmentID);
            Assert.Single(selectList);
        }

        // ─── Edit POST Tests ───

        [Fact]
        public void Edit_Post_ValidCourse_NoFile_SavesAndRedirects()
        {
            var dept = CreateDepartment();
            var course = CreateCourse(6001, "Literature", 3, dept.DepartmentID);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editedCourse = new Course
            {
                CourseID = 6001,
                Title = "Modern Literature",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Edit(editedCourse, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidExtension_AddsModelError()
        {
            var dept = CreateDepartment();
            var course = CreateCourse(6002, "Philosophy", 3, dept.DepartmentID);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editedCourse = new Course
            {
                CourseID = 6002,
                Title = "Philosophy",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("virus.exe");
