             Assert.NotNull(notification);
             Assert.Contains("Student", notification.Message);
             Assert.Contains("42", notification.Message);
             Assert.Equal("Student", notification.EntityType);
             Assert.Equal("42", notification.EntityId);
         }

         [Fact]
         public void ReceiveNotification_EmptyQueue_ReturnsNull()
         {
             var result = _service.ReceiveNotification();

             Assert.Null(result);
         }

         [Fact]
         public void ReceiveNotification_DequeuesInOrder()
         {
             _service.SendNotification("Type", "1", "First", EntityOperation.CREATE, "admin");
             _service.SendNotification("Type", "2", "Second", EntityOperation.UPDATE, "admin");
             _service.SendNotification("Type", "3", "Third", EntityOperation.DELETE, "admin");

             var first = _service.ReceiveNotification();
             var second = _service.ReceiveNotification();
             var third = _service.ReceiveNotification();

             Assert.Equal("1", first.EntityId);
             Assert.Equal("2", second.EntityId);
             Assert.Equal("3", third.EntityId);
         }

         [Fact]
         public void MarkAsRead_DoesNotThrow()
         {
             var exception = Record.Exception(() => _service.MarkAsRead(999));

             Assert.Null(exception);
         }

         [Fact]
         public void Dispose_DoesNotThrow()
         {
             var service = new NotificationService();

             var exception = Record.Exception(() => service.Dispose());

             Assert.Null(exception);
         }

         [Fact]
         public void QueueCap_ExceedingMaxLength_OldestItemsDropped()
         {
             for (int i = 0; i < 510; i++)
             {
                 _service.SendNotification("Item", i.ToString(), $"Item {i}", EntityOperation.CREATE, "admin");
             }

             int count = 0;
             while (_service.ReceiveNotification() != null)
             {
                 count++;
             }

             Assert.True(count <= 500, $"Queue should be capped at 500 but had {count} items");
         }
     }
 }

