        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 9001,
                Title = "Art",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = CreateValidImageFile("painting.png");

            var result = _controller.Create(course, mockFile.Object);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);

            var saved = _context.Courses.Find(9001);
            Assert.NotNull(saved);
            Assert.StartsWith("/Uploads/TeachingMaterials/course_9001_", saved.TeachingMaterialImagePath);
            Assert.EndsWith(".png", saved.TeachingMaterialImagePath);
        }

