            {
                CourseID = 9005,
                Title = "Dance",
                Credits = 2,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editedCourse = new Course
            {
                CourseID = 9005,
                Title = "Dance",
                Credits = 2,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("large.jpg");
            mockFile.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB

            var result = _controller.Edit(editedCourse, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_InvalidModelState_ReturnsView()
        {
            var dept = CreateDepartment();
            _controller.ModelState.AddModelError("Title", "Required");

            var course = new Course
            {
                CourseID = 9006,
                Title = "",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Edit(course, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Course>(viewResult.Model);
        }

        // ─── DeleteConfirmed with file cleanup ───

        [Fact]
        public void DeleteConfirmed_WithImageFile_DeletesFileFromDisk()
        {
            var dept = CreateDepartment();
            var dir = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(dir);
            var filePath = Path.Combine(dir, "course_delete_test.jpg");
            File.WriteAllText(filePath, "fake image");

            var course = new Course
            {
                CourseID = 9007,
                Title = "Pottery",
                Credits = 2,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/course_delete_test.jpg"
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            _controller.DeleteConfirmed(9007);

            Assert.False(File.Exists(filePath));
        }

        [Fact]
        public void DeleteConfirmed_WithoutImageFile_DoesNotThrow()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 9008,
                Title = "Weaving",
                Credits = 2,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = null
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var exception = Record.Exception(() => _controller.DeleteConfirmed(9008));

            Assert.Null(exception);
        }

        [Fact]
        public void Edit_Post_ValidCourse_SendsUpdateNotification()
        {
            NotificationQueueHelper.DrainQueue();
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 9009,
                Title = "Ceramics",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editedCourse = new Course
            {
                CourseID = 9009,
                Title = "Advanced Ceramics",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            _controller.Edit(editedCourse, null);

            using var svc = new NotificationService();
            var notification = svc.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Contains("Advanced Ceramics", notification.Message);
        }
    }
}

