using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests : IDisposable
    {
        private readonly SchoolContext _context;

        public DbInitializerTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose()
        {
            _context?.Dispose();
        }

        [Fact]
        public void Initialize_SeedsStudents()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.Students.Count());
        }

        [Fact]
        public void Initialize_SeedsInstructors()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(5, _context.Instructors.Count());
        }

        [Fact]
        public void Initialize_SeedsDepartments()
        {
            DbInitializer.Initialize(_context);

            var departments = _context.Departments.ToList();
            Assert.Equal(4, departments.Count);
            Assert.Contains(departments, d => d.Name == "English");
            Assert.Contains(departments, d => d.Name == "Mathematics");
            Assert.Contains(departments, d => d.Name == "Engineering");
            Assert.Contains(departments, d => d.Name == "Economics");
        }

        [Fact]
        public void Initialize_SeedsCourses()
        {
            DbInitializer.Initialize(_context);

            var courses = _context.Courses.ToList();
            Assert.Equal(7, courses.Count);
            Assert.Contains(courses, c => c.Title == "Chemistry" && c.CourseID == 1050);
            Assert.Contains(courses, c => c.Title == "Calculus" && c.CourseID == 1045);
        }

        [Fact]
        public void Initialize_SeedsOfficeAssignments()
        {
            DbInitializer.Initialize(_context);

            var offices = _context.OfficeAssignments.ToList();
            Assert.Equal(3, offices.Count);
            Assert.Contains(offices, o => o.Location == "Smith 17");
            Assert.Contains(offices, o => o.Location == "Gowan 27");
            Assert.Contains(offices, o => o.Location == "Thompson 304");
        }

        [Fact]
        public void Initialize_SeedsCourseAssignments()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_SeedsEnrollments()
        {
            DbInitializer.Initialize(_context);

            var enrollments = _context.Enrollments.ToList();
            Assert.Equal(11, enrollments.Count);
            Assert.Contains(enrollments, e => e.Grade == Grade.A);
            Assert.Contains(enrollments, e => e.Grade == null);
        }

        [Fact]
        public void Initialize_DepartmentsHaveAdministrators()
        {
            DbInitializer.Initialize(_context);

            var departments = _context.Departments.ToList();
            Assert.All(departments, d => Assert.NotNull(d.InstructorID));
        }

        [Fact]
        public void Initialize_CalledTwice_DoesNotDuplicateData()
        {
            DbInitializer.Initialize(_context);
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.Students.Count());
            Assert.Equal(5, _context.Instructors.Count());
            Assert.Equal(4, _context.Departments.Count());
            Assert.Equal(7, _context.Courses.Count());
        }

        [Fact]
        public void Initialize_StudentNames_AreCorrect()
        {
            DbInitializer.Initialize(_context);

            var students = _context.Students.OrderBy(s => s.LastName).ToList();
            Assert.Equal("Alexander", students[0].LastName);
            Assert.Equal("Carson", students[0].FirstMidName);
            Assert.Equal("Olivetto", students.Last().LastName);
        }

        [Fact]
        public void Initialize_InstructorHireDates_AreSet()
        {
            DbInitializer.Initialize(_context);

            var instructors = _context.Instructors.ToList();
            Assert.All(instructors, i => Assert.True(i.HireDate > new DateTime(1990, 1, 1)));
        }

        [Fact]
        public void Initialize_CoursesHaveDepartments()
        {
            DbInitializer.Initialize(_context);

            var courses = _context.Courses.ToList();
            Assert.All(courses, c => Assert.True(c.DepartmentID > 0));
        }

        [Fact]
        public void Initialize_DepartmentBudgets_ArePositive()
        {
            DbInitializer.Initialize(_context);

            var departments = _context.Departments.ToList();
            Assert.All(departments, d => Assert.True(d.Budget > 0));
        }

        [Fact]
        public void Initialize_EnrollmentsDontDuplicateOnRerun()
        {
            DbInitializer.Initialize(_context);
            var firstCount = _context.Enrollments.Count();

            // Simulate re-running on existing DB (students exist, so Initialize returns early)
            DbInitializer.Initialize(_context);
            var secondCount = _context.Enrollments.Count();

            Assert.Equal(firstCount, secondCount);
        }
    }
}

using System;
using System.IO;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerFileUploadTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _tempDir;

        public CoursesControllerFileUploadTests()
        {
            NotificationQueueHelper.DrainQueue();

            _context = TestDbContextFactory.Create();
            _tempDir = Path.Combine(Path.GetTempPath(), "contoso_test_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(_tempDir);

            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);

            _mockLogger = new Mock<ILogger<CoursesController>>();

            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), Mock.Of<ITempDataProvider>());
        }

        public void Dispose()
        {
            _controller?.Dispose();
            _context?.Dispose();
            try { if (Directory.Exists(_tempDir)) Directory.Delete(_tempDir, true); } catch { }
        }

        private Department CreateDepartment()
        {
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 100000m,
                StartDate = new DateTime(2023, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Mock<IFormFile> CreateValidImageFile(string fileName = "photo.jpg", long size = 1024)
        {
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns(fileName);
            mockFile.Setup(f => f.Length).Returns(size);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));
            return mockFile;
        }

        // ─── Create POST with valid file upload ───

        [Fact]
        public void Create_Post_ValidFile_SavesCourseWithImagePath()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 9001,
                Title = "Art",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = CreateValidImageFile("painting.png");

            var result = _controller.Create(course, mockFile.Object);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);

            var saved = _context.Courses.Find(9001);
            Assert.NotNull(saved);
            Assert.StartsWith("/Uploads/TeachingMaterials/course_9001_", saved.TeachingMaterialImagePath);
            Assert.EndsWith(".png", saved.TeachingMaterialImagePath);
        }

        [Theory]
        [InlineData("image.jpg")]
        [InlineData("image.jpeg")]
        [InlineData("image.png")]
        [InlineData("image.gif")]
        [InlineData("image.bmp")]
        public void Create_Post_AllowedExtensions_Succeeds(string fileName)
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 9100 + fileName.GetHashCode() % 1000,
                Title = "TestCourse",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = CreateValidImageFile(fileName);

            var result = _controller.Create(course, mockFile.Object);

            Assert.IsType<RedirectToActionResult>(result);
        }

        [Fact]
        public void Create_Post_FileUploadCreatesDirectory()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 9002,
                Title = "Music",
                Credits = 2,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = CreateValidImageFile("photo.jpg");

            _controller.Create(course, mockFile.Object);

            var uploadsDir = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
            Assert.True(Directory.Exists(uploadsDir));
        }

        // ─── Edit POST with valid file upload ───

        [Fact]
        public void Edit_Post_ValidFile_UpdatesImagePath()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 9003,
                Title = "Drama",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editedCourse = new Course
            {
                CourseID = 9003,
                Title = "Drama",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = CreateValidImageFile("newphoto.png");

            var result = _controller.Edit(editedCourse, mockFile.Object);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_ValidFile_DeletesOldFile()
        {
            var dept = CreateDepartment();
            // Create the old file on disk
            var oldDir = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(oldDir);
            var oldFilePath = Path.Combine(oldDir, "old_image.jpg");
            File.WriteAllText(oldFilePath, "fake image data");

            var course = new Course
            {
                CourseID = 9004,
                Title = "Sculpture",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/old_image.jpg"
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editedCourse = new Course
            {
                CourseID = 9004,
                Title = "Sculpture",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/old_image.jpg"
            };
            var mockFile = CreateValidImageFile("newphoto.jpg");

            _controller.Edit(editedCourse, mockFile.Object);

            Assert.False(File.Exists(oldFilePath));
        }

        [Fact]
        public void Edit_Post_FileTooLarge_AddsModelError()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 9005,
                Title = "Dance",
                Credits = 2,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editedCourse = new Course
            {
                CourseID = 9005,
                Title = "Dance",
                Credits = 2,
                DepartmentID = dept.DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("large.jpg");
            mockFile.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB

            var result = _controller.Edit(editedCourse, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_InvalidModelState_ReturnsView()
        {
            var dept = CreateDepartment();
            _controller.ModelState.AddModelError("Title", "Required");

            var course = new Course
            {
                CourseID = 9006,
                Title = "",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Edit(course, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Course>(viewResult.Model);
        }

        // ─── DeleteConfirmed with file cleanup ───

        [Fact]
        public void DeleteConfirmed_WithImageFile_DeletesFileFromDisk()
        {
            var dept = CreateDepartment();
            var dir = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(dir);
            var filePath = Path.Combine(dir, "course_delete_test.jpg");
            File.WriteAllText(filePath, "fake image");

            var course = new Course
            {
                CourseID = 9007,
                Title = "Pottery",
                Credits = 2,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/course_delete_test.jpg"
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            _controller.DeleteConfirmed(9007);

            Assert.False(File.Exists(filePath));
        }

        [Fact]
        public void DeleteConfirmed_WithoutImageFile_DoesNotThrow()
        {
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 9008,
                Title = "Weaving",
                Credits = 2,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = null
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var exception = Record.Exception(() => _controller.DeleteConfirmed(9008));

            Assert.Null(exception);
        }

        [Fact]
        public void Edit_Post_ValidCourse_SendsUpdateNotification()
        {
            NotificationQueueHelper.DrainQueue();
            var dept = CreateDepartment();
            var course = new Course
            {
                CourseID = 9009,
                Title = "Ceramics",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editedCourse = new Course
            {
                CourseID = 9009,
                Title = "Advanced Ceramics",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            _controller.Edit(editedCourse, null);

            using var svc = new NotificationService();
            var notification = svc.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Contains("Advanced Ceramics", notification.Message);
        }
    }
}

