using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests : IDisposable
    {
        private readonly SchoolContext _context;

        public DbInitializerTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose()
        {
            _context?.Dispose();
        }

        [Fact]
        public void Initialize_SeedsStudents()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.Students.Count());
        }

        [Fact]
        public void Initialize_SeedsInstructors()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(5, _context.Instructors.Count());
        }

        [Fact]
        public void Initialize_SeedsDepartments()
        {
            DbInitializer.Initialize(_context);

            var departments = _context.Departments.ToList();
            Assert.Equal(4, departments.Count);
            Assert.Contains(departments, d => d.Name == "English");
            Assert.Contains(departments, d => d.Name == "Mathematics");
            Assert.Contains(departments, d => d.Name == "Engineering");
            Assert.Contains(departments, d => d.Name == "Economics");
        }

        [Fact]
        public void Initialize_SeedsCourses()
        {
            DbInitializer.Initialize(_context);

            var courses = _context.Courses.ToList();
            Assert.Equal(7, courses.Count);
            Assert.Contains(courses, c => c.Title == "Chemistry" && c.CourseID == 1050);
            Assert.Contains(courses, c => c.Title == "Calculus" && c.CourseID == 1045);
        }

        [Fact]
        public void Initialize_SeedsOfficeAssignments()
        {
            DbInitializer.Initialize(_context);

            var offices = _context.OfficeAssignments.ToList();
            Assert.Equal(3, offices.Count);
            Assert.Contains(offices, o => o.Location == "Smith 17");
            Assert.Contains(offices, o => o.Location == "Gowan 27");
            Assert.Contains(offices, o => o.Location == "Thompson 304");
        }

        [Fact]
        public void Initialize_SeedsCourseAssignments()
        {
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_SeedsEnrollments()
        {
            DbInitializer.Initialize(_context);

            var enrollments = _context.Enrollments.ToList();
            Assert.Equal(11, enrollments.Count);
            Assert.Contains(enrollments, e => e.Grade == Grade.A);
            Assert.Contains(enrollments, e => e.Grade == null);
        }

        [Fact]
        public void Initialize_DepartmentsHaveAdministrators()
        {
            DbInitializer.Initialize(_context);

            var departments = _context.Departments.ToList();
            Assert.All(departments, d => Assert.NotNull(d.InstructorID));
        }

        [Fact]
        public void Initialize_CalledTwice_DoesNotDuplicateData()
        {
            DbInitializer.Initialize(_context);
            DbInitializer.Initialize(_context);

            Assert.Equal(8, _context.Students.Count());
            Assert.Equal(5, _context.Instructors.Count());
            Assert.Equal(4, _context.Departments.Count());
            Assert.Equal(7, _context.Courses.Count());
        }

        [Fact]
        public void Initialize_StudentNames_AreCorrect()
        {
            DbInitializer.Initialize(_context);

            var students = _context.Students.OrderBy(s => s.LastName).ToList();
            Assert.Equal("Alexander", students[0].LastName);
            Assert.Equal("Carson", students[0].FirstMidName);
            Assert.Equal("Olivetto", students.Last().LastName);
        }

        [Fact]
        public void Initialize_InstructorHireDates_AreSet()
        {
            DbInitializer.Initialize(_context);

            var instructors = _context.Instructors.ToList();
            Assert.All(instructors, i => Assert.True(i.HireDate > new DateTime(1990, 1, 1)));
        }

        [Fact]
        public void Initialize_CoursesHaveDepartments()
        {
            DbInitializer.Initialize(_context);

            var courses = _context.Courses.ToList();
            Assert.All(courses, c => Assert.True(c.DepartmentID > 0));
        }

        [Fact]
        public void Initialize_DepartmentBudgets_ArePositive()
        {
            DbInitializer.Initialize(_context);

            var departments = _context.Departments.ToList();
            Assert.All(departments, d => Assert.True(d.Budget > 0));
        }

        [Fact]
        public void Initialize_EnrollmentsDontDuplicateOnRerun()
        {
            DbInitializer.Initialize(_context);
            var firstCount = _context.Enrollments.Count();

            DbInitializer.Initialize(_context);
            var secondCount = _context.Enrollments.Count();

            Assert.Equal(firstCount, secondCount);
        }
    }
}

